mapper.sql:
WHERE p.deleted = 0 AND p.status = 1 AND NOT EXISTS ( SELECT 1 FROM seckill_activity_apply saa JOIN seckill_activity sa ON sa.id = saa.activity_id WHERE saa.product_id = p.id AND saa.audit_status = 1 AND sa.publish_status = 1 AND sa.end_time > CURRENT_TIMESTAMP )
AND p.category_id = #{categoryId}
AND ( p.name LIKE CONCAT('%', #{part}, '%') OR p.description LIKE CONCAT('%', #{part}, '%') OR JSON_CONTAINS(p.tags, CONCAT('\"', #{part}, '\"')) )
AND p.price >= #{minPrice}
AND p.price <= #{maxPrice}
